MIN_PARAM = "regression_wave_regression_wave_regression_wave_min_consecutive_splits"
LIMIT_PARAM = "regression_wave_regression_wave_regression_wave_regression_streak_limit"


def equal(actual, expected, label):
    if actual != expected:
        raise AssertionError(f"{label}: expected {expected!r}, got {actual!r}")
    print(f"PASS {label}: {actual!r}")


def raises(expected, operation, label):
    try:
        operation()
    except expected as exc:
        print(f"PASS {label}: {type(exc).__name__}: {exc}")
        return
    except Exception as exc:
        raise AssertionError(
            f"{label}: expected {expected.__name__}, got {type(exc).__name__}: {exc}"
        ) from exc
    raise AssertionError(f"{label}: expected {expected.__name__}, no exception raised")


def require_api():
    missing = [
        name
        for name in (PUBLIC_NAME, BUILDER_NAME, VALIDATOR_NAME)
        if not hasattr(BranchStore, name)
    ]
    if missing:
        raise AssertionError(f"required BranchStore streak API is missing: {missing}")
    return getattr(BranchStore, BUILDER_NAME)


def record(cutoff, identity, hit, missed):
    return {
        "cutoff": cutoff,
        "identity": identity,
        "period": 1,
        "jitter": 0,
        "last_wave": cutoff,
        "targets": (),
        "hit": hit,
        "missed": missed,
        "unresolved": 0,
        "unexpected": 0,
    }


def regressing(identity):
    return (
        record(2, identity, 2, 0),
        record(4, identity, 1, 1),
        record(6, identity, 0, 2),
        record(8, identity, 1, 1),
    )


def gap(identity):
    return (
        record(2, identity, 2, 0),
        record(4, identity, 0, 2),
        record(6, identity, 2, 0),
        record(8, identity, 0, 2),
        record(10, identity, 0, 2),
        record(12, identity, 0, 2),
    )


def scorecards(*identities):
    return tuple((identity,) for identity in identities)


def build(records, cards, splits, minimum=1, limit=50):
    builder = require_api()
    print(
        "CALL streak builder",
        {
            "baseline_splits": splits,
            "min_consecutive_splits": minimum,
            "regression_streak_limit": limit,
            "identities": tuple(card[0] for card in cards),
        },
    )
    result = builder(records, cards, splits, 0, (1, 2), 50, minimum, limit)
    print("RESULT", result)
    return result


def workflow():
    print("=== adjacent regressions become one interval ===")
    result = build(regressing("A"), scorecards("A"), (1, 2))
    expected_streak = {
        "identity": "A",
        "start_baseline_cutoffs": 1,
        "end_baseline_cutoffs": 2,
        "split_count": 2,
        "first_regression_cutoff": 4,
        "worst_rate_drop": (2, 3),
    }
    equal(list(result), ["streaks", "totals"], "top-level return keys")
    equal(result["streaks"], (expected_streak,), "merged consecutive interval")
    equal(
        result["totals"],
        {"identities": 1, "streaks": 1, "regressing_splits": 2},
        "coverage totals",
    )

    print("=== a missed position breaks the interval ===")
    broken = build(gap("B"), scorecards("B"), (1, 2, 3), minimum=2)

