def kept_scorecards(*identities):
    return tuple((identity,) for identity in identities)


def regressing_records(identity):
    return (
        backtest_record(2, identity, 2, 0),
        backtest_record(4, identity, 1, 1),
        backtest_record(6, identity, 0, 2),
        backtest_record(8, identity, 1, 1),
    )


def gap_records(identity):
    return (
        backtest_record(2, identity, 2, 0),
        backtest_record(4, identity, 0, 2),
        backtest_record(6, identity, 2, 0),
        backtest_record(8, identity, 0, 2),
        backtest_record(10, identity, 0, 2),
        backtest_record(12, identity, 0, 2),
    )


# 1. Signature: swap + append, token last.
names = list(inspect.signature(STREAKS).parameters)
regression_names = list(
    inspect.signature(getattr(BranchStore, REGRESSIONS_QUERY)).parameters
)
expected = [
    f"{PREFIX}_baseline_splits" if n == f"{PREFIX}_baseline_cutoffs" else n
    for n in regression_names[:-1]
] + [
    f"{PREFIX}_min_consecutive_splits",
    f"{PREFIX}_regression_streak_limit",
    "token",
]
assert names == expected, names[-8:]
params = list(inspect.signature(STREAKS).parameters.values())
assert all(p.default is inspect.Parameter.empty for p in params[:-1])
assert params[-1].default is None
print("signature OK")

# 2. Builder: adjacent hits connect, key order, totals.
result = build_streaks(
    regressing_records("A"), kept_scorecards("A"), (1, 2), 0, (1, 2), 50, 1, 50
)
assert list(result) == ["streaks", "totals"]
assert isinstance(result["streaks"], tuple)
streak = result["streaks"][0]
assert list(streak) == [
    "identity",
    "start_reference_cutoffs",
    "end_reference_cutoffs",
    "split_count",
    "first_regression_cutoff",
    "worst_rate_drop",
], list(streak)
assert streak == {
    "identity": "A",
    "start_reference_cutoffs": 1,
    "end_reference_cutoffs": 2,
    "split_count": 2,
    "first_regression_cutoff": 4,
    "worst_rate_drop": (2, 3),
}, streak
assert result["totals"] == {"identities": 1, "streaks": 1, "regressing_splits": 2}
print("builder connect OK")

# 3. Gap breaks the run; min_consecutive_splits filters.
result = build_streaks(gap_records("B"), kept_scorecards("B"), (1, 2, 3), 0, (1, 2), 50, 1, 50)
assert len(result["streaks"]) == 1
assert result["streaks"][0]["split_count"] == 1
assert result["streaks"][0]["start_reference_cutoffs"] == 1
assert result["totals"] == {"identities": 1, "streaks": 1, "regressing_splits": 1}
result = build_streaks(gap_records("B"), kept_scorecards("B"), (1, 2, 3), 0, (1, 2), 50, 2, 50)
assert result["streaks"] == ()
assert result["totals"] == {"identities": 0, "streaks": 0, "regressing_splits": 0}
print("gap/min-consecutive OK")

# 4. Streak limit raises without truncating; regression limit per split.
try:
    build_streaks(
        regressing_records("A") + regressing_records("C"),
        kept_scorecards("A", "C"), (1, 2), 0, (1, 2), 50, 1, 1,
    )
except ValueError as exc:
    assert "regression streak limit" in str(exc), exc
else:
    raise AssertionError("expected streak limit ValueError")
try:
    build_streaks(
        regressing_records("A") + regressing_records("C"),
        kept_scorecards("A", "C"), (1, 2), 0, (1, 2), 1, 1, 50,
    )
except ValueError as exc:
    assert "regression limit" in str(exc), exc
else:
    raise AssertionError("expected regression limit ValueError")
print("limits OK")

# 5. Empty input.
result = build_streaks((), (), (1,), 0, (0, 1), 50, 1, 50)
assert result["streaks"] == ()
assert result["totals"] == {"identities": 0, "streaks": 0, "regressing_splits": 0}
print("empty OK")

# 6. Fresh objects.
result = build_streaks(regressing_records("A"), kept_scorecards("A"), (1,), 0, (0, 1), 50, 1, 50)
result["streaks"][0]["split_count"] = 999
result["totals"]["streaks"] = 999
again = build_streaks(regressing_records("A"), kept_scorecards("A"), (1,), 0, (0, 1), 50, 1, 50)
assert again["streaks"][0]["split_count"] == 1
assert again["totals"]["streaks"] == 1
print("freshness OK")

# 7. Public query on the diamond store matches the builder applied to
# the public deepest backtests/scorecards queries.
store, args = diamond_store()
kwargs = regressions_kwargs(args)
kwargs[f"{PREFIX}_baseline_splits"] = (1,)
del kwargs[f"{PREFIX}_baseline_cutoffs"]
kwargs[f"{PREFIX}_min_consecutive_splits"] = 1
kwargs[f"{PREFIX}_regression_streak_limit"] = 50
result = getattr(store, STREAKS_QUERY)(**kwargs)
assert list(result) == ["streaks", "totals"]
assert result["totals"] == {"identities": 0, "streaks": 0, "regressing_splits": 0}
print("public query OK:", result)

# 8. Validation errors on the public query.
def call(**overrides):
    merged = dict(kwargs)
    merged.update(overrides)
    return getattr(store, STREAKS_QUERY)(**merged)

for bad in (True, 1, 1.0, "1", None, [1, 2], (True, 1), (1.0, 2)):
    try:
        call(**{f"{PREFIX}_baseline_splits": bad})
    except TypeError:
        pass
    else:
        raise AssertionError(f"expected TypeError for {bad!r}")
for bad in ((), (0,), (-1, 2), (1, 1), (2, 1)):
    try:
        call(**{f"{PREFIX}_baseline_splits": bad})
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for {bad!r}")
for name in (f"{PREFIX}_min_consecutive_splits", f"{PREFIX}_regression_streak_limit"):
    for bad in (True, 1.0, "1", None):
        try:
            call(**{name: bad})
        except TypeError:
            pass
        else:
            raise AssertionError(f"expected TypeError for {name}={bad!r}")
    for bad in (0, -2):
        try:
            call(**{name: bad})
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {name}={bad!r}")
# Validation precedes state lookup.
try:
    call(reference="ghost", **{f"{PREFIX}_baseline_splits": "x"})
except TypeError:
    pass
else:
    raise AssertionError("expected TypeError before state lookup")
print("validation OK")

# 9. Token semantics: success consumes one read, failure refunds.
token = store.create_snapshot(2)
call(token=token)
try:
    call(token=token, drift_limit=2)
except ValueError:
    pass
call(token=token)
try:
    call(token=token)
except RuntimeError:
    pass
else:
    raise AssertionError("expected expired token RuntimeError")
print("token OK")

