import ast, sys, collections

src = open("offline_coordination/replication.py").read()
lines = src.splitlines()
tree = ast.parse(src)

# map top-level defs to ranges
defs = {}  # name -> (start,end,kind)
for node in tree.body:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        defs[node.name] = (node.lineno, node.end_lineno, type(node).__name__)
    elif isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name):
                defs[t.id] = (node.lineno, node.end_lineno, "assign")
            elif isinstance(t, ast.Tuple):
                for e in t.elts:
                    if isinstance(e, ast.Name):
                        defs[e.id] = (node.lineno, node.end_lineno, "assign")
    elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
        defs[node.target.id] = (node.lineno, node.end_lineno, "assign")

R1 = (46564, 48653)   # final fork decision aggregate CHAIN (supersede/verify/batch/head anchor)
R2 = (48654, len(lines))  # final fork decision aggregate chain FORK proof/decision/aggregate

def segment(lineno):
    for i,(a,b) in enumerate((R1,R2),1):
        if a <= lineno <= b:
            return i
    return 0
